await (async(page)=>{const card=page.getByRole('heading',{name:'A Phase 1 Study of BB102 in Participants With Advanced Solid Tumors',exact:true}).locator('xpath=../../..');const popupPromise=page.waitForEvent('popup');await card.getByRole('link',{name:'View Trial',exact:true}).click();const popup=await popupPromise;await popup.getByText('A Phase 1 Study of BB102 in Participants With Advanced Solid Tumors',{exact:true}).first().waitFor({timeout:60000});const text=await popup.locator('body').innerText();const result={url:popup.url(),hasTitle:text.includes('BB102'),hasEligibility:text.includes('Eligibility Criteria'),hasLocations:text.includes('Locations'),containsMeningeal:text.includes('meninges')};await popup.close();return result;})(page);
